const exchangeRateCache = new Map();
async function getExchangeRate(currency,date){
  const base=String(currency||'AUD').trim().toUpperCase();
  const requestedDate=String(date||todayInputValue()).replaceAll('.','-');
  const key=`${base}:${requestedDate}`;
  if(exchangeRateCache.has(key))return exchangeRateCache.get(key);
  const promise=fetch(`/api/exchange-rate?base=${encodeURIComponent(base)}&quote=CNY&date=${encodeURIComponent(requestedDate)}`,{credentials:'same-origin'}).then(async response=>{const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'暂时无法取得交易日汇率。');const rate=Number(result.rate);if(!Number.isFinite(rate)||rate<=0)throw new Error('汇率服务未返回有效结果。');return {...result,rate};}).catch(error=>{exchangeRateCache.delete(key);throw error;});
  exchangeRateCache.set(key,promise);
  return promise;
}
