let entries = []; let assets = []; let activeFilter = 'all'; let entryMode = 'single'; let scannedReceipt = null; let receiptQueue = []; let selectionMode = false; let selectedEntryIds = new Set(); let homePeriod = 'month'; let customCategories = []; let ledgerDateStart = ''; let ledgerDateEnd = '';
const $ = s => document.querySelector(s); const $$ = s => [...document.querySelectorAll(s)];
const SYSTEM_CATEGORIES = ['日用','餐饮','购物','交通','学习','其他'];
const money = n => `A$${Number(n).toFixed(2)}`;
const entryDate = entry => String(entry.date||'').replaceAll('.','-');
const monthKey = date => String(date||'').slice(0,7);
const THEME_KEY = 'liuxue-spending-theme-v1';
function applyTheme(theme){const next=['icewine','citrus','frost','guava','orchard'].includes(theme)?theme:'ins';document.body.dataset.theme=next;localStorage.setItem(THEME_KEY,next);$$('[data-theme-choice]').forEach(button=>button.classList.toggle('selected',button.dataset.themeChoice===next));}
function updateFilterBadge(){const badge=$('#filterButton i');if(badge)badge.textContent=String((ledgerDateStart?1:0)+(ledgerDateEnd?1:0));}
function allCategories(){return [...SYSTEM_CATEGORIES,...customCategories.filter(category=>!SYSTEM_CATEGORIES.includes(category))];}
function categoryOptions(selected='日用'){const options=allCategories();if(selected&&!options.includes(selected)&&selected!=='__custom__')options.push(selected);return `${options.map(category=>`<option value="${escapeText(category)}" ${category===selected?'selected':''}>${escapeText(category)}</option>`).join('')}<option value="__custom__">＋ 自定义分类…</option>`;}
function refreshCategoryPreferences(){const preference=$('#categoryPreference');if(preference)preference.textContent=`${SYSTEM_CATEGORIES.length} 个系统分类${customCategories.length?`，${customCategories.length} 个自定义分类`:''}`;$$('[data-category-select]').forEach(select=>{const value=select.value||'日用';select.innerHTML=categoryOptions(value);});}
async function loadCustomCategories(){try{const categories=await window.ledgerApi?.getCategories?.();customCategories=Array.isArray(categories)?categories:[];}catch{customCategories=[];}refreshCategoryPreferences();}
function currentMonthEntries(){ const currentMonth=new Date().toISOString().slice(0,7); return entries.filter(entry=>!entry.hidden&&monthKey(entryDate(entry))===currentMonth); }
function homePeriodData(){
  const now=new Date(); const localToday=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
  const month=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`; const year=String(now.getFullYear());
  const all=entries.filter(entry=>!entry.hidden); let items=all; let label='全部记录'; let totalLabel='全部实付'; let description='统计所有已确认、未隐藏的交易记录。';
  if(homePeriod==='month'){items=all.filter(entry=>monthKey(entryDate(entry))===month);label=`${now.getFullYear()} 年 ${now.getMonth()+1} 月`;totalLabel='本月实付';description='仅统计交易日期落在当前月份的消费。';}
  if(homePeriod==='year'){items=all.filter(entry=>entryDate(entry).slice(0,4)===year);label=`${now.getFullYear()} 年`;totalLabel='本年实付';description='仅统计交易日期落在当前年份的消费。';}
  if(homePeriod==='week'){const start=new Date(now);start.setDate(now.getDate()-6);start.setHours(0,0,0,0);items=all.filter(entry=>{const date=entryDate(entry);return date>=`${start.getFullYear()}-${String(start.getMonth()+1).padStart(2,'0')}-${String(start.getDate()).padStart(2,'0')}`&&date<=localToday;});label='近 7 天';totalLabel='近 7 天实付';description='按交易日期统计最近 7 天的消费。';}
  return {items,label,totalLabel,description};
}
function renderHomeTrend(monthEntries){
  const chart=$('#homeTrendChart');
  if(!chart)return;
  const valuesByDay=new Map();
  monthEntries.forEach(entry=>{const day=Number(entryDate(entry).slice(-2));if(Number.isFinite(day))valuesByDay.set(day,(valuesByDay.get(day)||0)+Number(entry.amount||0));});
  const days=[...valuesByDay.keys()].sort((a,b)=>a-b);
  if(!days.length){chart.classList.add('empty-chart');chart.innerHTML='<p>本月暂无消费趋势</p>';return;}
  const max=Math.max(...valuesByDay.values(),1);
  const points=days.map((day,index)=>{const x=days.length===1?310:index/(days.length-1)*620;const y=164-valuesByDay.get(day)/max*122;return `${x.toFixed(1)},${y.toFixed(1)}`;});
  const first=points[0].split(','); const last=points[points.length-1].split(',');
  chart.classList.remove('empty-chart');
  chart.innerHTML=`<svg viewBox="0 0 620 190" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".28"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient></defs><path class="area" d="M${first[0]} 190 L${points.join(' L')} L${last[0]} 190 Z"/><path class="chart-path" d="M${points.join(' L')}"/></svg><div class="axis">${days.map(day=>`<span>${day}日</span>`).join('')}</div>`;
}
function renderCategorySummary(sourceEntries=currentMonthEntries()){
  const container=$('#categorySummary');
  if(!container)return;
  const categoryTotals=new Map();
  sourceEntries.forEach(entry=>{const category=entry.category||'其他';categoryTotals.set(category,(categoryTotals.get(category)||0)+Number(entry.amount||0));});
  const categories=[...categoryTotals.entries()].filter(([,amount])=>amount>0).sort((a,b)=>b[1]-a[1]);
  if(!categories.length){container.innerHTML='<div class="donut empty-donut"><div><strong>0</strong><span>个分类</span></div></div><div class="category-empty"><b>还没有消费记录</b><p>记一笔后，这里会按真实账目自动生成分类与占比。</p></div>';return;}
  const total=categories.reduce((sum,[,amount])=>sum+amount,0);
  const colors=['var(--chart-1,#e88c91)','var(--chart-2,#bfe7f0)','var(--chart-3,#cff1d2)','var(--chart-4,#d2eaa6)','var(--chart-5,#f8ecd7)','var(--chart-6,#b5eae5)','var(--chart-7,#b2ba69)'];
  let progress=0;
  const gradient=categories.map(([,amount],index)=>{const start=progress;progress+=amount/total*100;return `${colors[index%colors.length]} ${start}% ${progress}%`;}).join(',');
  container.innerHTML=`<div class="donut" style="background:conic-gradient(${gradient})"><div><strong>${categories.length}</strong><span>个分类</span></div></div><ul class="legend">${categories.map(([category,amount],index)=>`<li><i class="dot" style="background:${colors[index%colors.length]}"></i><span>${escapeText(category)}</span><b>${money(amount)}</b><em>${(amount/total*100).toFixed(0)}%</em></li>`).join('')}</ul>`;
}
function refreshSummary(){ const visibleEntries=entries.filter(e=>!e.hidden); const period=homePeriodData(); const total=period.items.reduce((sum,e)=>sum+Number(e.amount||0),0); const cny=period.items.reduce((sum,e)=>sum+Number(e.cny||0),0); const assetCny=assets.reduce((sum,asset)=>sum+(Number(String(asset.cny??0).replace(/[^\d.-]/g,''))||0),0); const aud=$('#monthAud'); const cnyEl=$('#monthCny'); const comparison=$('#monthComparison'); const recent=$('#recentTotal'); const assetCount=$('#assetCount'); const assetCost=$('#assetCost'); const periodLabel=$('#homePeriodLabel'); const totalLabel=$('#homeTotalLabel'); const description=$('#homePeriodDescription'); if(aud) aud.textContent=total.toLocaleString('en-AU',{minimumFractionDigits:2,maximumFractionDigits:2}); if(cnyEl) cnyEl.textContent=`¥${cny.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`; if(comparison) comparison.textContent=period.items.length?`${period.label}已记录 ${period.items.length} 笔商品消费`:`${period.label}还没有消费记录`; if(periodLabel)periodLabel.textContent=period.label;if(totalLabel)totalLabel.textContent=period.totalLabel;if(description)description.textContent=period.description;if(recent) recent.textContent=visibleEntries.length; if(assetCount) assetCount.textContent=assets.length; if(assetCost) assetCost.textContent=`¥${assetCny.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`; renderHomeTrend(period.items); renderCategorySummary(period.items); renderStats(); }
function renderStats(){ const statsCards=$$('#statsView .stats-cards article'); const currentMonth=new Date().toISOString().slice(0,7); const monthEntries=currentMonthEntries(); const total=monthEntries.reduce((sum,entry)=>sum+Number(entry.amount||0),0); const cny=monthEntries.reduce((sum,entry)=>sum+Number(entry.cny||0),0); const previousDate=new Date(`${currentMonth}-01T00:00:00`); previousDate.setMonth(previousDate.getMonth()-1); const previousMonth=previousDate.toISOString().slice(0,7); const previousEntries=entries.filter(entry=>!entry.hidden&&monthKey(entryDate(entry))===previousMonth); const previousTotal=previousEntries.reduce((sum,entry)=>sum+Number(entry.amount||0),0); const comparison=previousEntries.length?`${previousTotal===0?'—':`${total>=previousTotal?'↑':'↓'} ${Math.abs((total-previousTotal)/previousTotal*100).toFixed(1)}%`} 环比`:'暂无上月记录'; const activeDays=new Set(monthEntries.map(entry=>entryDate(entry))).size; if(statsCards.length===3){statsCards[0].innerHTML=`<span>本月消费</span><strong>${money(total)}</strong><small>≈ ¥${cny.toFixed(2)}</small><em>${comparison}</em>`;statsCards[1].innerHTML=`<span>本月商品记录</span><strong>${monthEntries.length} <small>笔</small></strong><em>${activeDays?`发生在 ${activeDays} 天`:'暂无消费记录'}</em>`;statsCards[2].innerHTML=`<span>单笔平均</span><strong>${money(monthEntries.length?total/monthEntries.length:0)}</strong><em>${monthEntries.length?'按商品级账目计算':'暂无消费记录'}</em>`;}
  const valuesByDay=new Map(); monthEntries.forEach(entry=>{const day=Number(entryDate(entry).slice(-2));if(Number.isFinite(day))valuesByDay.set(day,(valuesByDay.get(day)||0)+Number(entry.amount||0));}); const days=[...valuesByDay.keys()].sort((a,b)=>a-b); const chart=$('#barChart'); if(chart){const max=Math.max(...valuesByDay.values(),1);chart.innerHTML=days.length?days.map(day=>`<div class="bar" title="${day} 日 · ${money(valuesByDay.get(day))}"><i style="height:${Math.max(5,valuesByDay.get(day)/max*100)}%"></i><span>${day}</span></div>`).join(''):'<p class="empty">本月暂无消费记录。</p>';}
  const merchants=new Map(); monthEntries.forEach(entry=>merchants.set(entry.merchant,(merchants.get(entry.merchant)||0)+Number(entry.amount||0))); const ranked=[...merchants.entries()].sort((a,b)=>b[1]-a[1]).slice(0,5); const merchantList=$('#statsView .merchant-rank'); if(merchantList){merchantList.closest('.panel').querySelector('.section-title p').textContent=`本月去过 ${merchants.size} 家商户`;merchantList.innerHTML=ranked.length?ranked.map(([merchant,amount],index)=>`<li><span>${index+1}</span><div class="merchant-initial">${escapeText(merchant.slice(0,1).toUpperCase())}</div><b>${escapeText(merchant)}</b><em>${money(amount)}</em></li>`).join(''):'<li class="empty">本月暂无商家数据。</li>';}
  const consumable=monthEntries.filter(entry=>!entry.asset).reduce((sum,entry)=>sum+Number(entry.amount||0),0); const asset=monthEntries.filter(entry=>entry.asset).reduce((sum,entry)=>sum+Number(entry.amount||0),0); const distribution=$('#statsView .distribution'); if(distribution){const consumableWidth=total?consumable/total*100:0;distribution.innerHTML=`<div class="section-title"><div><h2>支出分布</h2><p>消耗品与非消耗品</p></div></div><div class="split-bar"><span style="width:${consumableWidth}%"></span><i style="width:${100-consumableWidth}%"></i></div><div class="split-label"><span><i class="dot violet"></i>消耗品 <b>${total?(consumable/total*100).toFixed(0):0}%</b> · ${money(consumable)}</span><span><i class="dot peach"></i>非消耗品 <b>${total?(asset/total*100).toFixed(0):0}%</b> · ${money(asset)}</span></div>`;}}
async function saveLedger(){ if(!window.ledgerApi)return; try{ await window.ledgerApi.save(entries,assets); }catch(error){ showToast(error.message||'云端保存失败，请检查网络后重试'); } }
async function hydrateLedger(){ try{ const [ledger]=await Promise.all([window.ledgerApi.get(),loadCustomCategories()]); entries=Array.isArray(ledger.entries)?ledger.entries:[]; assets=Array.isArray(ledger.assets)?ledger.assets:[]; renderEntries();renderAssets();refreshSummary(); showToast(entries.length?'已加载你的云端账本':'这是你的第一本账，开始记录吧'); }catch(error){ showToast(error.message||'暂时无法读取云端账本'); } }
function filteredLedgerEntries() {
  const term = ($('#ledgerSearch')?.value || '').toLowerCase();
  return entries.filter(e => {
    const match = `${e.name} ${e.cn} ${e.merchant} ${e.category}`.toLowerCase().includes(term);
    const visibility=activeFilter==='hidden'?e.hidden:!e.hidden;
    const date=entryDate(e); const inDateRange=(!ledgerDateStart||date>=ledgerDateStart)&&(!ledgerDateEnd||date<=ledgerDateEnd);
    const kind = activeFilter === 'all' || activeFilter==='hidden' || (activeFilter === 'asset' && e.asset) || (activeFilter === 'consumable' && !e.asset) || (activeFilter === 'hasReceipt' && e.receipt) || e.key === activeFilter;
    return match && visibility && kind && inDateRange;
  });
}
function updateBatchControls(items=filteredLedgerEntries()) {
  const selectedCount=selectedEntryIds.size;
  const active=selectionMode;
  $('#ledgerTable')?.classList.toggle('selection-mode',active);
  $('#batchManage').hidden=active;
  $('#batchActions').hidden=!active;
  $('#batchSelectionCount').textContent=`已选 ${selectedCount} 项`;
  $('#batchDeleteEntries').disabled=selectedCount===0;
  const allSelected=items.length>0&&items.every(item=>selectedEntryIds.has(item.id));
  $('#selectAllEntries').textContent=allSelected?'取消全选':'全选';
  const selectAll=$('#selectAllVisibleEntries'); if(selectAll){selectAll.checked=allSelected;selectAll.indeterminate=selectedCount>0&&!allSelected;}
}
function renderEntries() {
  const items=filteredLedgerEntries();
  selectedEntryIds=new Set([...selectedEntryIds].filter(id=>entries.some(entry=>entry.id===id)));
  const row = e => `<div class="ledger-row ${selectedEntryIds.has(e.id)?'is-selected':''}" data-entry="${e.id}"><label class="entry-select"><input type="checkbox" data-entry-select="${e.id}" ${selectedEntryIds.has(e.id)?'checked':''} aria-label="选择 ${escapeText(e.cn||e.name)}" /></label><div><div class="product-image ${e.type}">${e.icon}</div><div><div class="product-name">${e.name}</div><div class="product-meta">${e.cn} · ${e.detail}${e.hidden?' · 已隐藏':''}</div></div></div><span class="merchant">${e.merchant}</span><span class="date">${e.date}</span><span class="category"><i class="category-tag">${e.category}</i></span><span class="amount">${money(e.amount)}<small>¥${e.cny.toFixed(2)}</small></span><div class="row-actions"><button class="more-row" aria-label="更多操作">···</button><div class="entry-menu" hidden><button data-entry-action="edit">编辑</button><button data-entry-action="hide">${e.hidden?'取消隐藏':'隐藏'}</button><button class="danger" data-entry-action="delete">删除</button></div></div></div>`;
  $('#ledgerList').innerHTML = items.map(row).join('') || '<p class="empty">没有找到匹配的商品记录。</p>';
  $('#recentList').innerHTML = entries.filter(e=>!e.hidden).slice(0,4).map(e => `<div class="recent-row" data-entry="${e.id}"><div><div class="product-image ${e.type}">${e.icon}</div><div><div class="product-name">${e.name}</div><div class="product-meta">${e.cn}${e.asset ? ' · 非消耗品' : ''}</div></div></div><span class="merchant">${e.merchant}</span><span class="date">${e.date.slice(5)}</span><span class="amount">${money(e.amount)}<small>¥${e.cny.toFixed(2)}</small></span></div>`).join('') || '<p class="empty">还没有消费记录，点击“记一笔”开始。</p>';
  updateBatchControls(items); updateFilterBadge();
  $$('#ledgerList [data-entry], #recentList [data-entry]').forEach(el => el.addEventListener('click', ev => { const id=Number(el.dataset.entry); const action=ev.target.closest('[data-entry-action]')?.dataset.entryAction; if(action){ev.stopPropagation(); if(action==='edit')openEditEntry(id); if(action==='hide')toggleHidden(id); if(action==='delete')deleteEntry(id); return;} const checkbox=ev.target.closest('[data-entry-select]'); if(checkbox){ev.stopPropagation(); if(checkbox.checked)selectedEntryIds.add(id);else selectedEntryIds.delete(id);renderEntries();return;} if(selectionMode&&el.closest('#ledgerList')){ev.stopPropagation();if(selectedEntryIds.has(id))selectedEntryIds.delete(id);else selectedEntryIds.add(id);renderEntries();return;} if(ev.target.closest('.more-row')){ev.stopPropagation(); const menu=el.querySelector('.entry-menu'); $$('.entry-menu').forEach(other=>{if(other!==menu)other.hidden=true;}); menu.hidden=!menu.hidden; return;} if(ev.target.closest('.entry-menu'))return; showDetail(id); }));
}
