function todayInputValue(){const today=new Date();return `${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;}
let ratePreviewRequest=0;
async function updateManualRatePreview(){const target=$('#ratePreview');if(!target)return;const request=++ratePreviewRequest;const amounts=[$('#entryForm [name=amount]'),...$$('#multipleEntryList [data-manual-amount]')].map(input=>Number(input?.value||0)).filter(Number.isFinite);const total=amounts.reduce((sum,amount)=>sum+amount,0);const currency=$('#entryForm [name=currency]')?.value||'AUD';const date=$('#entryForm [name=date]')?.value||todayInputValue();target.textContent='正在获取交易日汇率…';try{const quote=await getExchangeRate(currency,date);if(request!==ratePreviewRequest)return;target.textContent=`¥${(total*quote.rate).toFixed(2)}（1 ${currency} = ¥${quote.rate.toFixed(4)}，${quote.rateDate}）`;}catch(error){if(request!==ratePreviewRequest)return;target.textContent='汇率暂不可用，当前账目不会保存';}}
function manualItemRow(){return `<div class="manual-item-row" data-manual-item><div class="manual-item-heading"><b>新增商品</b><button class="remove-manual-item" type="button" aria-label="删除这件商品">删除</button></div><div class="form-grid manual-item-fields"><label>商品名称<input data-manual-name placeholder="如：保鲜袋" /></label><label>中文简称<input data-manual-cn placeholder="如：大号保鲜袋" /></label><label>实付金额<input data-manual-amount required type="number" min="0" step="0.01" placeholder="0.00" /></label><label>分类<select data-manual-category data-category-select>${categoryOptions()}</select></label><label>属性<div class="property-toggle"><input class="manual-item-asset" id="manualAsset-${Date.now()}-${Math.random().toString(36).slice(2)}" type="checkbox" /><label><span></span><em>设为非消耗品</em></label></div></label></div></div>`;}
