function renderCategoryManager(){const system=$('#systemCategoryList');const custom=$('#customCategoryList');if(system)system.innerHTML=`<p>系统分类</p><div>${SYSTEM_CATEGORIES.map(category=>`<span>${escapeText(category)}</span>`).join('')}</div>`;if(custom)custom.innerHTML=customCategories.length?`<p>我的自定义分类</p><div>${customCategories.map(category=>`<span>${escapeText(category)}<button type="button" data-remove-category="${escapeText(category)}" aria-label="删除 ${escapeText(category)}">×</button></span>`).join('')}</div>`:'<p class="empty-category">还没有自定义分类，例如可添加“水电费”。</p>';}
