async function handleCustomCategorySelect(select){if(select.value!=='__custom__')return;const name=window.prompt('请输入自定义分类名称（最多 20 个字符）：','')?.trim().replace(/\s+/g,' ');if(!name){select.innerHTML=categoryOptions('日用');return;}if(name.length>20){showToast('分类名称不超过 20 个字符。');select.innerHTML=categoryOptions('日用');return;}if(!allCategories().includes(name))await saveCustomCategories([...customCategories,name]);select.innerHTML=categoryOptions(name);showToast(`已选择自定义分类“${name}”。`);}
function showToast(text){ const el=$('#toast'); el.textContent=text; el.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer=setTimeout(()=>el.classList.remove('show'),2800); }
window.showLedgerToast=showToast;
async function openReceiptImage(receiptId){const modal=$('#receiptImageModal');const image=$('#receiptImageView');const status=$('#receiptImageStatus');if(!receiptId||!modal||!image||!status)return;$('#detailModal').hidden=true;image.hidden=true;image.removeAttribute('src');status.textContent='正在加载小票图片…';openModal('#receiptImageModal');try{let src='';if(String(receiptId).startsWith('guest-receipt-')){src=await window.guestReceiptStore?.get(receiptId)||'';}else{const response=await fetch(`/api/receipt-image?id=${encodeURIComponent(receiptId)}`,{credentials:'same-origin'});if(!response.ok){const result=await response.json().catch(()=>({}));throw new Error(result.error||'未找到已保存的小票。');}receiptObjectUrl=URL.createObjectURL(await response.blob());src=receiptObjectUrl;}if(!src)throw new Error('这张小票尚未保存到当前设备或云端。');image.src=src;image.hidden=false;status.textContent='可放大查看这张原始小票。';}catch(error){status.textContent='无法打开原始小票。';showToast(error.message||'无法打开原始小票。');}}
function receiptButton(receiptId){return receiptId?`<button class="receipt-link" type="button" data-receipt-id="${escapeText(receiptId)}">查看原始小票</button>`:'暂无凭证';}
function showDetail(id){ const e=entries.find(x=>x.id===id); if(!e)return; const receiptLink=e.receiptId?receiptButton(e.receiptId):(e.receipt?'已保存':'暂无凭证'); $('#detailModal').innerHTML=`<button class="modal-close" data-close>×</button><div class="detail-header"><div class="product-image ${e.type}">${e.icon}</div><div><h2>${e.name}</h2><p>${e.cn} · ${e.asset?'非消耗品':'消耗品'}</p></div></div><div class="translation-editor"><label>中文简称<input id="entryCn" value="${escapeText(e.cn||'')}" placeholder="填写中文简称" /></label><button id="saveEntryCn">保存</button></div><div class="detail-grid"><div><span>购买日期</span><b>${e.date}</b></div><div><span>商家</span><b>${e.merchant}</b></div><div><span>商品实付</span><b>${money(e.amount)}</b></div><div><span>锁定 CNY 成本</span><b>¥${e.cny.toFixed(2)}</b></div><div><span>商品分类</span><b>${e.category}</b></div><div><span>原始凭证</span><b>${receiptLink}</b></div></div><div class="detail-history"><h3>同商品历史</h3><p>${e.name === 'Full Cream Milk 2L' ? '7 月 28 日 · Woolworths · A$4.60（价格 ↑ 4.3%）' : '暂未发现同商品的历史购买记录。'}</p></div><button class="delete-entry" data-delete-entry="${e.id}">删除这项记账</button>`; openModal('#detailModal'); $('#detailModal [data-close]').onclick=closeModals; $('#detailModal [data-delete-entry]').onclick=()=>deleteEntry(e.id); $('#detailModal [data-receipt-id]')?.addEventListener('click',()=>openReceiptImage(e.receiptId)); $('#saveEntryCn').onclick=()=>{const cn=$('#entryCn').value.trim();if(!cn){showToast('请填写中文简称。');return;}e.cn=cn;renderEntries();saveLedger();showToast('中文简称已保存。');}; }
function showAsset(i){ const a=assets[i]; const receiptLink=receiptButton(a.receiptId); $('#detailModal').innerHTML=`<button class="modal-close" data-close>×</button><div class="detail-header"><div class="product-image ${a.art}">${a.icon}</div><div><h2>${a.name}</h2><p><span class="category-tag">${a.status}</span> · ${a.note}</p></div></div><div class="detail-grid"><div><span>购入日期</span><b>${a.desc.split(' · ')[1]}</b></div><div><span>购入商家</span><b>${a.desc.split(' · ')[0]}</b></div><div><span>原币购入成本</span><b>${a.amount}</b></div><div><span>锁定 CNY 成本</span><b>${a.cny}</b></div><div><span>存放位置</span><b>我的住所</b></div><div><span>原始凭证</span><b>${receiptLink}</b></div></div><div class="detail-history"><h3>物品备注</h3><p>可在这里补充保修、搬家、二手处理与出售金额等信息。</p></div>`; openModal('#detailModal'); $('#detailModal [data-close]').onclick=closeModals; $('#detailModal [data-receipt-id]')?.addEventListener('click',()=>openReceiptImage(a.receiptId)); }
const escapeText = value => String(value ?? '').replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const hasFiniteAmount = value => typeof value === 'number' && Number.isFinite(value);
const receiptItemRow = item => `<div class="receipt-edit-row ${item.needsReview?'needs-review':''}" data-receipt-row><label>商品<input class="receipt-item-name" value="${escapeText(item.name||'')}" placeholder="原始商品名称" /></label><label>中文简称<input class="receipt-item-cn" value="${escapeText(item.cn||'')}" placeholder="例如：墙面挂钩" /></label><label>分类<select class="receipt-item-category" data-category-select>${categoryOptions(item.category||'其他')}</select></label><label>金额<input class="receipt-item-amount" value="${hasFiniteAmount(item.amount)?item.amount.toFixed(2):''}" type="number" step="0.01" required /></label><label class="asset-choice"><input class="receipt-item-asset" type="checkbox" ${item.asset?'checked':''} /><span>非消耗品</span></label><button class="remove-receipt-item" type="button" aria-label="删除此项" title="删除此项">×</button></div>`;
function openReview(receipt=scannedReceipt){
  if(!receipt){ showToast('请先上传一张真实小票图片。'); return; }
  const currency=/^[A-Z]{3}$/.test(receipt.currency||'')?receipt.currency:'AUD';
  const date=/^\d{4}-\d{2}-\d{2}$/.test(receipt.date||'')?receipt.date:new Date().toISOString().slice(0,10);
  const receiptTotal=hasFiniteAmount(receipt.total)?receipt.total:null;
  const receiptTotalLabel=receiptTotal===null?'待填写':`${currency} ${receiptTotal.toFixed(2)}`;
  const items=receipt.items.length?receipt.items:[{name:'未能逐行识别，请手动填写',cn:'待补充中文简称',amount:receipt.total,category:'其他',asset:false,needsReview:true}];
  const confidence={high:'高',medium:'中等',low:'低'}[receipt.confidence]||'低';
  const rows=items.map(receiptItemRow).join('');
  const queuePosition=receiptQueue.indexOf(receipt); const queueLabel=receiptQueue.length>1?`第 ${queuePosition+1} / ${receiptQueue.length} 张小票 · `:'';
  $('#reviewModal').innerHTML=`<button class="modal-close" data-close>×</button><form id="receiptReviewForm"><div class="review-top"><div><p class="eyebrow">真实 AI 识别结果</p><h2>请核对后入账</h2><p>${queueLabel}<span class="confidence">● ${confidence}置信度</span> 标黄字段来自不确定的原始文字，可直接修改。</p></div><div class="receipt-thumb"><span>${escapeText(receipt.merchant||'未识别')}</span><i></i><i></i><i></i><b>${receiptTotalLabel}</b></div></div><div class="receipt-meta"><label>商家<input name="merchant" value="${escapeText(receipt.merchant||'未识别')}" required /></label><label>日期<input name="date" type="date" value="${date}" required /></label><label>币种<input name="currency" value="${currency}" maxlength="3" required /></label><label>小票总计<input name="total" value="${receiptTotal===null?'':receiptTotal.toFixed(2)}" type="number" min="0" step="0.01" required /></label></div><div class="review-summary"><span>小票实付 <b id="reviewTotal">${receiptTotalLabel}</b></span><span>商品合计 <b id="reviewItemsTotal">${currency} ${items.reduce((sum,item)=>sum+(Number(item.amount)||0),0).toFixed(2)}</b></span><span>差额会自动作为折扣/税费记录</span></div><div class="review-items"><div class="review-items-head"><b id="receiptItemCount">识别到 ${items.length} 项</b><button id="addReceiptItem" type="button">＋ 添加项目</button></div>${rows}</div><p class="combo-tip">组合优惠、满减、优惠券或会员折扣请作为单独项目保留，金额填负数；不会被当成购买商品。</p>${receipt.notes?.length?`<p class="scan-notes">识别说明：${escapeText(receipt.notes.join('；'))}</p>`:''}<button class="button primary review-confirm" type="submit">${receiptQueue.length>1?'确认并继续下一张':'确认并入账'} <span>→</span></button></form>`;
  closeModals(); openModal('#reviewModal');
  $('#reviewModal [data-close]').onclick=()=>{receiptQueue=[];scannedReceipt=null;closeModals();};
  const reviewItems=$('#reviewModal .review-items'); const itemRows=()=>[...reviewItems.querySelectorAll('[data-receipt-row]')];
  const updateItemsTotal=()=>{const rows=itemRows();const sum=rows.reduce((total,row)=>total+(Number(row.querySelector('.receipt-item-amount').value)||0),0);$('#reviewItemsTotal').textContent=`${currency} ${sum.toFixed(2)}`;$('#receiptItemCount').textContent=`识别到 ${rows.length} 项`;};
  $('#addReceiptItem').onclick=()=>{reviewItems.insertAdjacentHTML('beforeend',receiptItemRow({name:'',cn:'',category:'其他',amount:0,asset:false,needsReview:false}));updateItemsTotal();reviewItems.querySelector('[data-receipt-row]:last-child .receipt-item-name').focus();};
  reviewItems.addEventListener('click',event=>{const remove=event.target.closest('.remove-receipt-item');if(!remove)return;const row=remove.closest('[data-receipt-row]');if(itemRows().length===1){showToast('请至少保留一项；可将不需要的内容改为正确商品。');return;}row.remove();updateItemsTotal();});
  reviewItems.addEventListener('input',event=>{if(event.target.matches('.receipt-item-amount'))updateItemsTotal();});
  $('#receiptReviewForm').onsubmit=async event=>{
    event.preventDefault();
    const form=new FormData(event.currentTarget);
    const merchant=String(form.get('merchant')).trim();
    const finalCurrency=String(form.get('currency')).trim().toUpperCase();
    const total=Number(form.get('total'));
    const reviewedItems=itemRows().map(row=>{const amountInput=row.querySelector('.receipt-item-amount');const name=row.querySelector('.receipt-item-name').value.trim();const cn=row.querySelector('.receipt-item-cn').value.trim();return {name:name||cn,cn:cn||name,category:row.querySelector('.receipt-item-category').value,amount:Number(amountInput.value),hasAmount:amountInput.value.trim()!=='',asset:row.querySelector('.receipt-item-asset').checked};});
    if(!merchant||!Number.isFinite(total)||!reviewedItems.length||reviewedItems.some(item=>!item.name||!item.hasAmount||!Number.isFinite(item.amount))){showToast('请填写商家、商品名称或中文简称、小票总计和每项金额。');return;}
    const submit=event.currentTarget.querySelector('[type=submit]');
    submit.disabled=true;submit.textContent='正在保存小票…';
    const beforeEntries=entries.map(entry=>({...entry}));
    const beforeAssets=assets.map(asset=>({...asset}));
    try{
      const rateQuote=await getExchangeRate(finalCurrency,String(form.get('date')));
      const isGuest=!window.currentLedgerUser;let saved;
      if(isGuest){const receiptId=`guest-receipt-${crypto.randomUUID()}`;await window.guestReceiptStore.put(receiptId,receipt.image);saved={receiptId};}
      else{const upload=await fetch('/api/receipt-image',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({image:receipt.image})});saved=await upload.json();if(!upload.ok)throw new Error(saved.error||'小票保存失败。');}
      const entryBase={merchant,date:String(form.get('date')),currency:finalCurrency,exchangeRate:rateQuote.rate,rateDate:rateQuote.rateDate,rateSource:rateQuote.source,receipt:true,receiptId:saved.receiptId,detail:'AI 小票识别，已人工确认'};
      reviewedItems.forEach(item=>makeNewEntry({...entryBase,...item},false));
      const difference=Math.round((total-reviewedItems.reduce((sum,item)=>sum+item.amount,0))*100)/100;
      if(Math.abs(difference)>=0.01)makeNewEntry({name:difference<0?'小票优惠 / 折扣':'税费 / 小费 / 舍入',cn:difference<0?'小票优惠':'税费或小费',amount:difference,category:'其他',asset:false,...entryBase,detail:'为使明细与小票总计一致'},false);
      if(!window.ledgerApi)throw new Error('账本服务暂不可用，请稍后重试。');
      await window.ledgerApi.save(entries,assets);
      const currentIndex=receiptQueue.indexOf(receipt);if(currentIndex>=0)receiptQueue.splice(currentIndex,1);scannedReceipt=receiptQueue[0]||null;renderPending();
      if(scannedReceipt){showToast(`已保存，继续核对剩余 ${receiptQueue.length} 张小票。`);openReview(scannedReceipt);}
      else{closeModals();showToast(`已入账并保存原始小票：${finalCurrency} ${total.toFixed(2)}`);if(isGuest)setTimeout(()=>window.requestLedgerLogin?.('你的首张小票已在本机保存。登录后可同步账目与原始小票，并在其他设备查看。'),150);}
    }catch(error){
      entries=beforeEntries;assets=beforeAssets;renderEntries();renderAssets();refreshSummary();
      showToast(error.message||'小票保存失败，请重试。');submit.disabled=false;submit.innerHTML=receiptQueue.length>1?'确认并继续下一张 <span>→</span>':'确认并入账 <span>→</span>';
    }
  };
  // Do not await lookup: the user can start checking the receipt immediately.
  void enrichReceiptNamesInBackground(receipt);
}
function closeMobileSidebar(){document.body.classList.remove('sidebar-open');const button=$('#mobileMenu');if(button)button.setAttribute('aria-expanded','false');$('#sidebarBackdrop').hidden=true;}
function setView(view){ $$('.view').forEach(v=>v.classList.toggle('active',v.id===`${view}View`)); $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view)); closeMobileSidebar(); window.scrollTo({top:0,behavior:'smooth'}); }
async function toggleHidden(id){ const entry=entries.find(item=>item.id===id); if(!entry)return; entry.hidden=!entry.hidden; renderEntries();refreshSummary(); try{if(window.ledgerApi)await window.ledgerApi.save(entries,assets);showToast(entry.hidden?'已隐藏，可在“已隐藏”筛选中恢复。':'已恢复显示。');}catch(error){entry.hidden=!entry.hidden;renderEntries();refreshSummary();showToast('状态未能同步到云端，请稍后重试。');}}
async function enrichReceiptNamesInBackground(receipt){
  if(!receipt||receipt._nameEnrichmentRequested||!Array.isArray(receipt.items)||!receipt.items.some(item=>!String(item.cn||'').trim()||item.needsReview))return;
  receipt._nameEnrichmentRequested=true;
  const before=receipt.items.map(item=>({cn:item.cn||'',category:item.category||'其他',asset:Boolean(item.asset)}));
  try{
    const response=await fetch('/api/receipt-enrich',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({receipt})});
    const data=await response.json();
    if(!response.ok||!Array.isArray(data?.receipt?.items))return;
    data.receipt.items.forEach((item,index)=>{
      const target=receipt.items[index]; const original=before[index]; if(!target||!original)return;
      if(String(item.cn||'').trim())target.cn=String(item.cn).trim();
      if(item.category)target.category=item.category;
      if(typeof item.asset==='boolean')target.asset=item.asset;
      if(typeof item.needsReview==='boolean')target.needsReview=item.needsReview;
    });
    if(scannedReceipt!==receipt||$('#reviewModal')?.hidden)return;
    $$('#reviewModal [data-receipt-row]').forEach((row,index)=>{
      const item=receipt.items[index]; const original=before[index]; if(!item||!original)return;
      const cn=row.querySelector('.receipt-item-cn'); const category=row.querySelector('.receipt-item-category'); const asset=row.querySelector('.receipt-item-asset');
      if(cn&&(!cn.value.trim()||cn.value===original.cn))cn.value=item.cn||'';
      if(category&&category.value===original.category)category.value=item.category||'其他';
      if(asset&&asset.checked===original.asset)asset.checked=Boolean(item.asset);
    });
  }catch{ /* A scan result remains usable when optional name enrichment fails. */ }
}

function openEditEntry(id){ const entry=entries.find(item=>item.id===id); if(!entry)return; const date=(entry.date||'').replaceAll('.','-'); const currency=entry.currency||'AUD'; $('#detailModal').innerHTML=`<button class="modal-close" data-close>×</button><div class="modal-heading"><p class="eyebrow">编辑账目</p><h2>更新这笔消费</h2><p>商品名称和中文简称填写任一项即可。</p></div><form id="editEntryForm"><div class="form-grid"><label>商品名称<input name="name" value="${escapeText(entry.name)}" /></label><label>中文简称<input name="cn" value="${escapeText(entry.cn||'')}" /></label><label>商家<input name="merchant" value="${escapeText(entry.merchant)}" required /></label><label>实付金额<div class="money-input"><select name="currency"><option ${currency==='AUD'?'selected':''}>AUD</option><option ${currency==='USD'?'selected':''}>USD</option><option ${currency==='GBP'?'selected':''}>GBP</option></select><input name="amount" type="number" min="0" step="0.01" value="${Number(entry.amount).toFixed(2)}" required /></div></label><label>消费日期<input name="date" type="date" value="${date}" required /></label><label>分类<select name="category">${categoryOptions(entry.category||'日用')}</select></label><label>属性<div class="property-toggle"><input id="editAsset" type="checkbox" ${entry.asset?'checked':''} /><label for="editAsset"><span></span><em>设为非消耗品</em></label></div></label></div><button type="submit" class="button primary submit-entry">保存修改 <span>→</span></button></form>`; openModal('#detailModal'); $('#detailModal [data-close]').onclick=closeModals; $('#editEntryForm').onsubmit=async event=>{event.preventDefault(); const data=Object.fromEntries(new FormData(event.currentTarget)); const name=String(data.name).trim();const cn=String(data.cn).trim();if(!name&&!cn){showToast('请至少填写商品名称或中文简称。');return;}let rateQuote;try{rateQuote=await getExchangeRate(String(data.currency),String(data.date));}catch(error){showToast(error.message||'暂时无法取得交易日汇率，修改未保存。');return;}const old={...entry}; entry.name=name||cn;entry.cn=cn||name;entry.merchant=String(data.merchant).trim();entry.currency=String(data.currency);entry.amount=Number(data.amount);entry.exchangeRate=rateQuote.rate;entry.rateDate=rateQuote.rateDate;entry.rateSource=rateQuote.source;entry.cny=entry.amount*rateQuote.rate;entry.date=String(data.date).replaceAll('-','.');entry.category=String(data.category);entry.key=entry.category==='餐饮'?'Food':entry.category==='购物'?'Shopping':'Daily';entry.asset=$('#editAsset').checked; const assetIndex=assets.findIndex(asset=>asset.entryId===entry.id||(old.asset&&asset.name===old.name&&asset.desc===`${old.merchant} · ${old.date}`)); if(old.asset&&!entry.asset&&assetIndex>=0)assets.splice(assetIndex,1); if(!old.asset&&entry.asset)assets.unshift({entryId:entry.id,name:entry.name,desc:`${entry.merchant} · ${entry.date}`,amount:`${entry.currency==='AUD'?'A$ ':entry.currency+' '}${entry.amount.toFixed(2)}`,cny:`¥${entry.cny.toFixed(2)}`,icon:'📦',art:'tech',status:'在用',note:'由账目创建',receiptId:entry.receiptId||null}); if(old.asset&&entry.asset&&assetIndex>=0)Object.assign(assets[assetIndex],{entryId:entry.id,name:entry.name,desc:`${entry.merchant} · ${entry.date}`,amount:`${entry.currency==='AUD'?'A$ ':entry.currency+' '}${entry.amount.toFixed(2)}`,cny:`¥${entry.cny.toFixed(2)}`,receiptId:entry.receiptId||null}); renderEntries();renderAssets();refreshSummary();try{if(window.ledgerApi)await window.ledgerApi.save(entries,assets);closeModals();showToast('账目已更新。');}catch(error){Object.assign(entry,old);renderEntries();renderAssets();refreshSummary();showToast('修改未能同步到云端，请稍后重试。');}};}
async function deleteEntry(id){ const entry=entries.find(item=>item.id===id); if(!entry)return; const note=entry.asset?'删除后，对应的物品档案也会移除。':''; if(!window.confirm(`确定删除“${entry.name}”吗？此操作无法撤销。${note}`))return; const previousEntries=entries; const previousAssets=assets; entries=entries.filter(item=>item.id!==id); assets=assets.filter(asset=>asset.entryId!==id&&!(entry.asset&&asset.name===entry.name&&asset.desc===`${entry.merchant} · ${entry.date}`)); renderEntries();renderAssets();refreshSummary(); closeModals(); try{if(window.ledgerApi)await window.ledgerApi.save(entries,assets);}catch(error){entries=previousEntries;assets=previousAssets;renderEntries();renderAssets();refreshSummary();showToast('删除未能同步到云端，请稍后重试。');return;} if(entry.receiptId&&!entries.some(item=>item.receiptId===entry.receiptId)){try{await fetch(`/api/receipt-image?id=${encodeURIComponent(entry.receiptId)}`,{method:'DELETE',credentials:'same-origin'});}catch{showToast('账目已删除，但原始小票暂未清理。');return;}} showToast('已删除这项记账。');}
async function deleteSelectedEntries(){const ids=new Set(selectedEntryIds);const selected=entries.filter(entry=>ids.has(entry.id));if(!selected.length){showToast('请先选择要删除的账目。');return;}const assetsAffected=selected.some(entry=>entry.asset);if(!window.confirm(`确定删除选中的 ${selected.length} 条账目吗？此操作无法撤销。${assetsAffected?' 对应的非消耗品档案也会一并移除。':''}`))return;const previousEntries=entries;const previousAssets=assets;entries=entries.filter(entry=>!ids.has(entry.id));assets=assets.filter(asset=>!ids.has(asset.entryId)&&!selected.some(entry=>entry.asset&&asset.name===entry.name&&asset.desc===`${entry.merchant} · ${entry.date}`));selectedEntryIds.clear();selectionMode=false;renderEntries();renderAssets();refreshSummary();try{if(window.ledgerApi)await window.ledgerApi.save(entries,assets);}catch(error){entries=previousEntries;assets=previousAssets;selectionMode=true;selectedEntryIds=new Set(ids);renderEntries();renderAssets();refreshSummary();showToast('批量删除未能同步到云端，请稍后重试。');return;}const receiptIds=[...new Set(selected.map(entry=>entry.receiptId).filter(receiptId=>receiptId&&!entries.some(entry=>entry.receiptId===receiptId)))];const failures=[];for(const receiptId of receiptIds){try{const response=await fetch(`/api/receipt-image?id=${encodeURIComponent(receiptId)}`,{method:'DELETE',credentials:'same-origin'});if(!response.ok)failures.push(receiptId);}catch{failures.push(receiptId);}}showToast(failures.length?`已删除 ${selected.length} 条账目；${failures.length} 张原始小票暂未清理。`:`已删除 ${selected.length} 条账目。`);}
function makeNewEntry(data,persist=true){ const isAsset=data.asset; const amount=Number(data.amount); const curr=data.currency; const exchangeRate=Number(data.exchangeRate);if(!Number.isFinite(exchangeRate)||exchangeRate<=0)throw new Error('缺少有效的交易日汇率，账目未保存。');const cny=amount*exchangeRate; const name=String(data.name||'').trim()||String(data.cn||'').trim();const cn=String(data.cn||'').trim()||name; const e={id:Date.now()+entries.length,name,cn,merchant:data.merchant,date:data.date.replaceAll('-','.'),currency:curr,category:data.category,key:data.category==='餐饮'?'Food':data.category==='购物'?'Shopping':'Daily',amount,cny,exchangeRate,rateDate:data.rateDate||data.date,rateSource:data.rateSource||'Frankfurter daily reference rate',icon:isAsset?'📦':'🛍️',type:isAsset?'tech':'daily',asset:isAsset,hidden:false,receipt:Boolean(data.receipt),receiptId:data.receiptId||null,detail:data.detail||(isAsset?'非消耗品档案已创建':'手动记账')}; entries.unshift(e); if(isAsset) assets.unshift({entryId:e.id,name:e.name,desc:`${e.merchant} · ${e.date}`,amount:`${curr === 'AUD'?'A$ ':curr+' '}${amount.toFixed(2)}`,cny:`¥${cny.toFixed(2)}`,icon:e.icon,art:'tech',status:'在用',note:'手动创建',receiptId:data.receiptId||null}); renderEntries();renderAssets();refreshSummary();if(persist)saveLedger(); const manualEntries=entries.filter(item=>!item.receipt).length; if(!data.receipt&&!window.currentLedgerUser&&manualEntries===5)setTimeout(()=>window.requestLedgerLogin?.('你已手动记下 5 笔账目。登录后可将它们安全同步到账号，并跨设备查看。'),120); return e; }
function setup(){ applyTheme(localStorage.getItem(THEME_KEY)||'ins'); renderEntries();renderAssets();refreshSummary();renderPending();
  $$('[data-home-period]').forEach(button=>button.onclick=()=>{homePeriod=button.dataset.homePeriod||'month';$$('[data-home-period]').forEach(item=>item.classList.toggle('selected',item===button));refreshSummary();});
  $$('.nav-item').forEach(b=>b.onclick=()=>setView(b.dataset.view)); $$('[data-go]').forEach(b=>b.onclick=()=>setView(b.dataset.go)); $('#addButton').onclick=openEntry; $('#mobileAdd').onclick=openEntry; $('#mobileScan').onclick=()=>openModal('#scanModal'); $$('.open-add').forEach(b=>b.onclick=openEntry); $('#itemAdd').onclick=openEntry; $('#scanButton').onclick=()=>openModal('#scanModal'); $('#seePending').onclick=()=>$('#scanButton').click(); $('#mobileMenu').onclick=()=>{const open=!document.body.classList.contains('sidebar-open');document.body.classList.toggle('sidebar-open',open);$('#mobileMenu').setAttribute('aria-expanded',String(open));$('#sidebarBackdrop').hidden=!open;}; $('#sidebarBackdrop').onclick=closeMobileSidebar; $('#manageCategories').onclick=openCategoryManager; $('#categoryForm').onsubmit=async event=>{event.preventDefault();const input=$('#customCategoryName');const name=input.value.trim().replace(/\s+/g,' ');const message=$('#categoryFormMessage');if(!name){message.textContent='请输入分类名称。';return;}if(name.length>20){message.textContent='分类名称不超过 20 个字符。';return;}if(allCategories().includes(name)){message.textContent='这个分类已经存在。';return;}await saveCustomCategories([...customCategories,name]);if(!message.textContent.includes('失败'))input.value='';}; $('#customCategoryList').onclick=event=>{const button=event.target.closest('[data-remove-category]');if(button)saveCustomCategories(customCategories.filter(category=>category!==button.dataset.removeCategory));};
  $('#modalBackdrop').onclick=closeModals; $$('[data-close]').forEach(b=>b.onclick=closeModals); $('#filterButton').onclick=()=>{const panel=$('#dateRangeFilter');panel.hidden=!panel.hidden;}; $('#dateRangeFilter').onsubmit=event=>{event.preventDefault();const start=$('#ledgerDateStart').value;const end=$('#ledgerDateEnd').value;if(start&&end&&start>end){showToast('开始日期不能晚于结束日期。');return;}ledgerDateStart=start;ledgerDateEnd=end;renderEntries();showToast(start||end?'已按自定义时间范围筛选。':'已显示全部时间。');}; $('#clearDateRange').onclick=()=>{ledgerDateStart='';ledgerDateStart='';ledgerDateEnd='';$('#ledgerDateStart').value='';$('#ledgerDateEnd').value='';renderEntries();showToast('已清除时间范围筛选。');}; $$('[data-theme-choice]').forEach(button=>button.onclick=()=>applyTheme(button.dataset.themeChoice)); document.addEventListener('change',event=>{const select=event.target.closest?.('[data-category-select]');if(select)void handleCustomCategorySelect(select);});
  $('#batchManage').onclick=()=>{selectionMode=true;selectedEntryIds.clear();renderEntries();}; $('#cancelBatchManage').onclick=()=>{selectionMode=false;selectedEntryIds.clear();renderEntries();}; $('#selectAllEntries').onclick=()=>{const items=filteredLedgerEntries();const allSelected=items.length>0&&items.every(item=>selectedEntryIds.has(item.id));items.forEach(item=>allSelected?selectedEntryIds.delete(item.id):selectedEntryIds.add(item.id));renderEntries();}; $('#selectAllVisibleEntries').onchange=event=>{const items=filteredLedgerEntries();items.forEach(item=>event.target.checked?selectedEntryIds.add(item.id):selectedEntryIds.delete(item.id));renderEntries();}; $('#batchDeleteEntries').onclick=deleteSelectedEntries;
  $$('.filter-row .chip').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;$$('.filter-row .chip').forEach(x=>x.classList.toggle('selected',x===b));renderEntries();}); $('#ledgerSearch').oninput=renderEntries; $('#itemSearch').oninput=()=>{const q=$('#itemSearch').value.toLowerCase(); $$('.item-card').forEach(x=>x.style.display=x.textContent.toLowerCase().includes(q)?'block':'none');};
  $$('.mode-switch button').forEach(b=>b.onclick=()=>{$$('.mode-switch button').forEach(x=>x.classList.toggle('selected',x===b));entryMode=b.dataset.mode;updateManualEntryMode();showToast(entryMode==='multiple'?'多商品模式：可在下方继续添加商品':'单件快速记账模式');});
  $('#addManualItem').onclick=()=>{const list=$('#multipleEntryList');list.insertAdjacentHTML('beforeend',manualItemRow());list.lastElementChild.querySelector('[data-manual-amount]').oninput=updateManualRatePreview;list.lastElementChild.querySelector('.remove-manual-item').onclick=event=>{event.currentTarget.closest('[data-manual-item]').remove();updateManualRatePreview();};};
  $('#entryForm [name=amount]').oninput=updateManualRatePreview; $('#entryForm [name=currency]').onchange=updateManualRatePreview; $('#entryForm [name=date]').onchange=updateManualRatePreview; $('#entryForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;const data=Object.fromEntries(new FormData(form));const base={merchant:String(data.merchant).trim(),currency:String(data.currency),date:String(data.date),detail:'手动记账'};const items=[{name:String(data.name).trim(),cn:String(data.cn).trim(),amount:Number(data.amount),category:String(data.category),asset:$('#consumable').checked}];if(entryMode==='multiple')$$('#multipleEntryList [data-manual-item]').forEach(row=>items.push({name:row.querySelector('[data-manual-name]').value.trim(),cn:row.querySelector('[data-manual-cn]').value.trim(),amount:Number(row.querySelector('[data-manual-amount]').value),category:row.querySelector('[data-manual-category]').value,asset:row.querySelector('.manual-item-asset').checked}));items.forEach(item=>{item.name=item.name||item.cn;item.cn=item.cn||item.name;});if(!base.merchant||!base.date||items.some(item=>!item.name||!Number.isFinite(item.amount))){showToast('请补全商家、日期、金额，以及商品名称或中文简称。');return;}let rateQuote;try{rateQuote=await getExchangeRate(base.currency,base.date);}catch(error){showToast(error.message||'暂时无法取得交易日汇率，账目未保存。');return;}const rateBase={...base,exchangeRate:rateQuote.rate,rateDate:rateQuote.rateDate,rateSource:rateQuote.source};items.forEach(item=>makeNewEntry({...rateBase,...item},false));await saveLedger();closeModals();showToast(items.length>1?`已将 ${items.length} 件商品按 ${rateQuote.rateDate} 汇率记入同一笔消费`:(items[0].asset?'已入账，并创建物品档案':`已确认入账，按 ${rateQuote.rateDate} 汇率锁定 CNY 成本`));};
  const isHeic=file=>['image/heic','image/heif'].includes(String(file.type).toLowerCase())||/\.(heic|heif)$/i.test(file.name||'');
  const supportedReceiptImage=file=>['image/jpeg','image/png','image/webp'].includes(String(file.type).toLowerCase())||/\.(jpe?g|png|webp)$/i.test(file.name||'')||isHeic(file);
  const readAsDataUrl=file=>new Promise((resolve,reject)=>{ const reader=new FileReader(); reader.onerror=()=>reject(new Error('无法读取图片。')); reader.onload=()=>resolve(String(reader.result)); reader.readAsDataURL(file); });
  const normalizeReceiptImage=async file=>{
    if(!isHeic(file))return file;
    let converted;
    try{const {default:heic2any}=await import('heic2any');converted=await heic2any({blob:file,toType:'image/jpeg',quality:.92});}catch(error){throw new Error('这张 HEIC 图片未能在浏览器中转换，请在 iPhone 相册中“共享 → 存储为图像”后再试。');}
    const jpeg=Array.isArray(converted)?converted[0]:converted;
    if(!(jpeg instanceof Blob))throw new Error('HEIC 转换失败，请改用 JPG 后重试。');
    return new File([jpeg],String(file.name||'receipt').replace(/\.(heic|heif)$/i,'.jpg'),{type:'image/jpeg'});
  };
  const originalImageAsDataUrl=async file=>{ if(file.size>5_000_000)throw new Error('原始小票请控制在 5MB 以内。'); return readAsDataUrl(file); };
  const scanImageAsDataUrl=file=>new Promise((resolve,reject)=>{ const reader=new FileReader(); reader.onerror=()=>reject(new Error('无法读取图片。')); reader.onload=()=>{ const image=new Image(); image.onerror=()=>reject(new Error('该图片格式无法处理，请使用 JPG、PNG 或 WebP。')); image.onload=()=>{ const scale=Math.min(1,1800/Math.max(image.width,image.height)); const canvas=document.createElement('canvas'); canvas.width=Math.round(image.width*scale); canvas.height=Math.round(image.height*scale); canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height); let quality=.88; let output=canvas.toDataURL('image/jpeg',quality); while(output.length>600_000&&quality>.3){quality-=.06;output=canvas.toDataURL('image/jpeg',quality);} if(output.length>600_000) reject(new Error('图片仍然过大，请裁剪到小票区域后再试。')); else resolve(output); }; image.src=reader.result; }; reader.readAsDataURL(file); });
  const processing=async selectedFiles=>{
    const files=[...selectedFiles].slice(0,10); if(!files.length)return;
    const invalid=files.find(file=>!supportedReceiptImage(file)); if(invalid){showToast('请上传 HEIC、JPG、PNG 或 WebP 格式的小票图片。');return;}
    $('#scanUpload').hidden=true;$('#scanProcessing').hidden=false;
    const results=new Array(files.length); const failures=[]; let nextIndex=0; let completed=0;
    const scanOne=async index=>{
      const file=files[index];
      try{
        $('#processText').textContent=isHeic(file)?`正在转换并识别 ${completed+1} / ${files.length} 张 HEIC 小票…`:`正在并行识别 ${completed+1} / ${files.length} 张小票…`;
        const preparedFile=await normalizeReceiptImage(file);
        const [scanImage,originalImage]=await Promise.all([scanImageAsDataUrl(preparedFile),originalImageAsDataUrl(preparedFile)]);
        const response=await fetch('/api/scan-receipt',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({image:scanImage,mimeType:'image/jpeg'})});
        const data=await response.json(); if(!response.ok)throw new Error(data.error||'识别服务暂时不可用。');
        results[index]={...data.receipt,image:originalImage};
      }catch(error){failures.push(error instanceof Error?error.message:'识别服务暂时不可用。');}
      finally{completed++;$('#processText').textContent=`已完成 ${completed} / ${files.length} 张小票…`;}
    };
    const worker=async()=>{while(nextIndex<files.length){const index=nextIndex++;await scanOne(index);}};
    try{
      // Two at a time halves typical batch wait time without causing avoidable
      // OpenAI rate-limit failures or a burst of large image uploads.
      await Promise.all(Array.from({length:Math.min(2,files.length)},worker));
      const recognized=results.filter(Boolean); if(!recognized.length)throw new Error(failures[0]||'小票识别失败，请稍后重试。');
      receiptQueue=recognized; scannedReceipt=receiptQueue[0]; $('#scanModal').hidden=true; openReview(scannedReceipt);
      if(failures.length)showToast(`${recognized.length} 张已识别，${failures.length} 张未能识别：${failures[0]}`);
    }catch(error){showToast(error.message||'小票识别失败，请稍后重试。');}
    finally{$('#scanUpload').hidden=false;$('#scanProcessing').hidden=true;$('#fileInput').value='';$('#cameraInput').value='';}
  }; $('#fileInput').onchange=event=>processing(event.target.files||[]); $('#cameraButton').onclick=()=>$('#cameraInput').click(); $('#cameraInput').onchange=event=>processing(event.target.files||[]); $('#exportData').onclick=()=>showToast('已生成数据导出文件，下载将在浏览器中开始'); $('#syncButton').onclick=()=>showToast('已检查同步状态：所有数据均为最新');
}
